import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // Design tokens
  const colors = {
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    surface: 0x0b0b10,
  };

  // Dimensions for collection row
  const width = 7;
  const height = 0.6;

  // Create geometry
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load and configure texture
  const texture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create main material
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  // Create main mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Create focus edge (accent border)
  const edgeGeometry = new THREE.PlaneGeometry(width + 0.1, height + 0.1);
  const edgeMaterial = new THREE.MeshBasicNodeMaterial({
    color: colors.accent,
    side: THREE.DoubleSide,
    wireframe: true,
    opacity: 0,
    transparent: true,
  });
  const edgeMesh = new THREE.Mesh(edgeGeometry, edgeMaterial);
  edgeMesh.position.z = 0.01;

  // Container group
  const group = new THREE.Group();
  group.add(mesh);
  group.add(edgeMesh);

  // Apply scene position
  const pos = config.scenePosition || { x: 0, y: 0.7, z: 0 };
  group.position.set(pos.x || 0, pos.y || 0.7, pos.z || 0);

  // Apply rotation
  if (config.rotation) {
    group.rotation.order = 'XYZ';
    group.rotation.set(
      config.rotation.x || 0,
      config.rotation.y || 0,
      config.rotation.z || 0
    );
  }

  // Apply scale
  if (config.scale) {
    group.scale.set(
      config.scale.x || 1,
      config.scale.y || 1,
      config.scale.z || 1
    );
  }

  const baseY = group.position.y;

  // Animation timelines
  let hoverTimeline = null;
  let clickTimeline = null;
  let focusTimeline = null;

  // Event handlers
  const handlers = {
    hover: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    unhover: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    click: (event) => {
      if (clickTimeline) clickTimeline.kill();
      clickTimeline = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1,
            y: 1,
            duration: 0.12,
            ease: 'back.out',
          });
        },
      });

      group.dispatchEvent({
        type: 'hub-collection.select',
        originalEvent: event,
      });
    },
    focus: () => {
      if (focusTimeline) focusTimeline.kill();
      focusTimeline = gsap.to(edgeMaterial, {
        opacity: 1,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    blur: () => {
      if (focusTimeline) focusTimeline.kill();
      focusTimeline = gsap.to(edgeMaterial, {
        opacity: 0,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
  };

  group.userData.handlers = handlers;

  // Cleanup
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();
    if (focusTimeline) focusTimeline.kill();
    geometry.dispose();
    edgeGeometry.dispose();
    material.dispose();
    edgeMaterial.dispose();
    texture.dispose();
  };

  return group;
}
